import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

final Uint8List jekiCreatorPhotoBytes = base64Decode(
  '',
);

class JekiCreatorImage extends StatelessWidget {
  final double? width;
  final double? height;
  final BoxFit fit;
  final Alignment alignment;

  const JekiCreatorImage({
    super.key,
    this.width,
    this.height,
    this.fit = BoxFit.cover,
    this.alignment = Alignment.topCenter,
  });

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      width: width,
      height: height,
      child: Image.memory(
        jekiCreatorPhotoBytes,
        width: width,
        height: height,
        fit: fit,
        alignment: alignment,
        gaplessPlayback: true,
      ),
    );
  }
}